    private static PartDefinition build_body(PartDefinition parent) {
        CubeListBuilder cubes = CubeListBuilder.create();
        PartDefinition part = parent.addOrReplaceChild("body", cubes, PartPose.offset(0.0000F, -32.0000F, 0.0000F));
        build_torso(part);
        build_skirt_front(part);
        build_skirt_back(part);
        build_lower_wing_left(part);
        build_lower_wing_right(part);
        build_cube_tail(part);
        build_fx_anchor(part);
        return part;
    }

    private static PartDefinition build_root(PartDefinition parent) {
        CubeListBuilder cubes = CubeListBuilder.create();
        PartDefinition part = parent.addOrReplaceChild("root", cubes, PartPose.offset(0.0000F, 24.0000F, 0.0000F));
        build_body(part);
        build_elemental_star_left(part);
        build_elemental_star_right(part);
        return part;
    }

